for w,g,b in [('panne','Названа неисправность отопления.','Цена и свободное время не сообщают о поломке.'),('chauffage','Названо отопление квартиры.','Спальня и диван — другие объекты.'),('fonctionner','Сообщается об исправной работе телевизора.','Местоположение прибора и желание смотреть его не означают, что он работает.'),('constater','Назван момент обнаружения неисправности.','Подготовка сообщения и доступность по времени не называют обнаружение.'),('ou-relatif','Работа человека связана с названным местом.','Другие модели описывают работу отопления или сообщение о неисправности.'),('reparer','Запрошено устранение неисправности.','Уточнение даты и подтверждение времени сами по себе не содержат просьбу починить.'),('dont-relatif','Назван предмет, о котором говорят.','Место работы и действие самого прибора требуют других выбранных моделей.'),('intervenir','Запрошен приход для устранения неисправности.','Цена и отмена визита — другие действия.'),('technicien','Назван специалист для устранения неисправности.','Владелец жилья и сосед не обозначают здесь приглашённого специалиста.')]:W[w]['review_items'][1]['feedback']=fb(g,b)

